import React from 'react';
import { Link } from 'react-router-dom';
// Import the social media icons you want to use
import { FaFacebookF, FaTwitter, FaInstagram, FaLinkedinIn } from 'react-icons/fa';

const styles = {
  footer: {
    backgroundColor: '#1a202c', // Dark blue background
    color: '#a0aec0', // Default light gray text color
    padding: '50px 30px',
    fontFamily: 'sans-serif',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  mainContent: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start', // Align items to the top
    flexWrap: 'wrap',
    gap: '30px',
    paddingBottom: '30px',
    marginBottom: '30px',
    borderBottom: '1px solid #2d3748', // The subtle horizontal line
  },
  branding: {
    textAlign: 'left',
  },
  clinicName: {
    color: '#ffffff',
    fontSize: '2rem',
    fontWeight: 'bold',
    margin: '0 0 8px 0',
  },
  tagline: {
    color: '#a0aec0',
    fontSize: '1rem',
    margin: 0,
    fontStyle: 'italic',
  },
  // --- New styles for social media ---
  socialsContainer: {
    marginTop: '20px',
    display: 'flex',
    gap: '15px', // Space between icons
  },
  // --- End of new styles ---
  nav: {
    display: 'flex',
    gap: '25px',
    flexWrap: 'wrap',
    marginTop: '10px', // Add some top margin for better alignment
  },
  copyright: {
    textAlign: 'center',
    fontSize: '0.9rem',
    color: '#a0aec0',
  }
};

// CSS for dynamic link and icon hover effects
const dynamicStyles = `
  .footer-nav-link {
    color: #a0aec0;
    text-decoration: none;
    font-size: 1rem;
    transition: color 0.3s ease;
  }

  .footer-nav-link:hover {
    color: #ffffff;
  }

  /* --- New styles for social icons --- */
  .social-icon {
    color: #1a202c; /* Icon color */
    background-color: #a0aec0; /* Background of the circle */
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    transition: background-color 0.3s ease, color 0.3s ease, transform 0.3s ease;
  }

  .social-icon:hover {
    background-color: #ffffff; /* Brighter background on hover */
    color: #1a202c;
    transform: translateY(-3px); /* Add a subtle lift effect */
  }
`;

const Footer = () => {
  const footerLinks = [
    { text: 'Home', path: '/', isRouterLink: true },
    { text: 'About Us', path: '/about', isRouterLink: true },
    { text: 'Services', path: '/#services', isRouterLink: false },
    { text: 'Contact Us', path: '/#contact', isRouterLink: false },
    { text: 'Terms and Conditions', path: '/terms', isRouterLink: true },
  ];

  return (
    <>
      <style>{dynamicStyles}</style>

      <footer style={styles.footer}>
        <div style={styles.container}>
          <div style={styles.mainContent}>
            {/* Left Column: Branding and Socials */}
            <div style={styles.branding}>
              <h2 style={styles.clinicName}>Karpagam Clinic</h2>
              <p style={styles.tagline}>Your Health, Our Priority</p>

              {/* --- Social Media Icons Section --- */}
              <div style={styles.socialsContainer}>
                <a href="https://facebook.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="Facebook">
                  <FaFacebookF />
                </a>
                <a href="https://twitter.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="Twitter">
                  <FaTwitter />
                </a>
                <a href="https://instagram.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="Instagram">
                  <FaInstagram />
                </a>
                <a href="https://linkedin.com" className="social-icon" target="_blank" rel="noopener noreferrer" aria-label="LinkedIn">
                  <FaLinkedinIn />
                </a>
              </div>
            </div>

            {/* Right Column: Navigation */}
            <nav style={styles.nav}>
              {footerLinks.map(({ text, path, isRouterLink }) => 
                isRouterLink ? (
                  <Link key={text} to={path} className="footer-nav-link">
                    {text}
                  </Link>
                ) : (
                  <a key={text} href={path} className="footer-nav-link">
                    {text}
                  </a>
                )
              )}
            </nav>
          </div>

          {/* Copyright Section */}
          <p style={styles.copyright}>
            © {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
          </p>
        </div>
      </footer>
    </>
  );
};

export default Footer;
